using GmailMailerApi.Models;
using MailKit.Net.Smtp;
using MailKit.Security;
using MimeKit;

namespace GmailMailerApi.Services;

/// <summary>
/// Sends emails using SMTP (MailKit). For Gmail, use App Password + STARTTLS on 587.
/// </summary>
public sealed class EmailService(SmtpOptions options, ILogger<EmailService> logger)
{
    private readonly SmtpOptions _opt = options;
    private readonly ILogger<EmailService> _log = logger;

    /// <summary>Sends an email with optional attachments.</summary>
    public async Task SendAsync(EmailRequestBase req, IFormFileCollection? attachments = null, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(_opt.Username) || string.IsNullOrWhiteSpace(_opt.Password))
            throw new InvalidOperationException("SMTP credentials are not configured.");

        if (string.IsNullOrWhiteSpace(req.Text) && string.IsNullOrWhiteSpace(req.Html))
            throw new ArgumentException("Provide at least 'Text' or 'Html' body.");

        using var message = new MimeMessage();

        // From
        var fromName = string.IsNullOrWhiteSpace(_opt.SenderDisplayName) ? _opt.Username : _opt.SenderDisplayName;
        message.From.Add(new MailboxAddress(fromName, _opt.Username));

        // To/Cc/Bcc
        foreach (var to in req.To) message.To.Add(MailboxAddress.Parse(to));
        if (req.Cc is { Count: > 0 })
            foreach (var cc in req.Cc) message.Cc.Add(MailboxAddress.Parse(cc));
        if (req.Bcc is { Count: > 0 })
            foreach (var bcc in req.Bcc) message.Bcc.Add(MailboxAddress.Parse(bcc));

        message.Subject = req.Subject;

        if (!string.IsNullOrWhiteSpace(req.ReplyTo))
            message.ReplyTo.Add(MailboxAddress.Parse(req.ReplyTo));

        var bodyBuilder = new BodyBuilder();

        if (!string.IsNullOrEmpty(req.Text)) bodyBuilder.TextBody = req.Text;
        if (!string.IsNullOrEmpty(req.Html)) bodyBuilder.HtmlBody = req.Html;

        if (attachments is { Count: > 0 })
        {
            foreach (var file in attachments)
            {
                if (file.Length <= 0) continue;
                using var ms = new MemoryStream();
                await file.CopyToAsync(ms, ct);
                ms.Position = 0;
                await bodyBuilder.Attachments.AddAsync(
                    file.FileName,
                    ms,
                    ContentType.Parse(file.ContentType ?? "application/octet-stream"),
                    ct);
            }
        }

        message.Body = bodyBuilder.ToMessageBody();

        using var smtp = new SmtpClient();
        try
        {
            await smtp.ConnectAsync(_opt.Host, _opt.Port, _opt.UseStartTls ? SecureSocketOptions.StartTls : SecureSocketOptions.Auto, ct);
            await smtp.AuthenticateAsync(_opt.Username, _opt.Password, ct);
            await smtp.SendAsync(message, ct);
        }
        catch (Exception ex)
        {
            _log.LogFailedSendingEmailViaSMTP(ex, ex.Message);
            throw;
        }
        finally
        {
            try { await smtp.DisconnectAsync(true, ct); } catch { /* ignore */ }
        }
    }
}

# @axa-fr/slimfaas-planet-saver

[![npm version](https://badge.fury.io/js/%40axa-fr%2Fslimfaas-planet-saver.svg)](https://badge.fury.io/js/%40axa-fr%2Fslimfaas-planet-saver)

![SlimFaas](../../docs/SlimFaas.png)

A Vanilla JS project to save the planet. SlimFaas (https://github.com/SlimPlanet/slimfaas) is the slimmest and simplest Function As A Service on Kubernetes.
It works as a proxy that you can be deployed in your namespace.

SlimFaas API can give to the frontend information about the infrastructure state. **It is a mind changer !**

**Why?**

Because in production instead of setting up 2 replicas of your API backend, you can set up 0 replicas and use an UX that will show the user that the backend is down instead !
**@axa-fr/slimfaas-planet-saver** is here to for doing that easy.

![SlimFaas Planet Saver](../../docs/SlimFaasPlanetSaver.gif)

## Getting Started

```javascript
npm install @axa-fr/slimfaas-planet-saver
```

Example usage with react :
```javascript
import React, { useState, useEffect, useRef } from 'react';
import { SlimFaasPlanetSaver } from '@axa-fr/slimfaas-planet-saver';

const PlanetSaver = ({ children, baseUrl, fetch, noActivityTimeout=60000, behavior={} }) => {
    const [isFirstStart, setIsFirstStart] = useState(true);
    const instanceRef = useRef(null);

    useEffect(() => {
        if (!baseUrl) return;

        if (instanceRef.current) return;

        const instance = new SlimFaasPlanetSaver(baseUrl, {
            interval: 2000,
            fetch,
            behavior,
            updateCallback: (data) => {
                const inst = instanceRef.current;
                // Filter only the items that block the UI (WakeUp+BlockUI)
                const blockingItems = data.filter(
                    (item) => inst?.getBehavior(item.Name) === 'WakeUp+BlockUI'
                );

                // If all blocking items are ready, set isFirstStart to false
                const allBlockingReady = blockingItems.every(
                    (item) => item.NumberReady >= 1
                );
                if (allBlockingReady && isFirstStart) {
                    setIsFirstStart(false);
                }
            },
            errorCallback: (error) => {
                console.error('Error detected :', error);
            },
            overlayStartingMessage: '🌳 Starting the environment.... 🌳',
            overlayNoActivityMessage: 'Waiting activity to start environment...',
            overlayErrorMessage: 'An error occurred when starting environment. Please contact an administrator.',
            overlaySecondaryMessage: 'Startup should be fast, but if no machines are available it can take several minutes.',
            overlayLoadingIcon: '🌍',
            overlayErrorSecondaryMessage: 'If the error persists, please contact an administrator.',
            noActivityTimeout
        });

        instanceRef.current = instance;

        // Initialiser les effets de bord
        instance.initialize();
        instance.startPolling();

        return () => {
            try {
                instance.cleanup();
            } finally {
                instanceRef.current = null;
            }
        };
    }, [baseUrl]);

    if (isFirstStart) {
        return null;
    }

    return <>{children}</>;
};

export default PlanetSaver;



```

### Usage:

```jsx
const behavior: {
    "api-speech-to-text": "WakeUp",
    "heavy-pdf-service": "WakeUp+BlockUI",
    "deprecated-service": "None"
}

<PlanetSaver baseUrl="http://slimfaas.mycompany.com" fetch={window.fetch} behavior={behavior}>
  <App />
</PlanetSaver>
```

---

## Run the demo

```javascript
git clone https://github.com/SlimPlanet/slimfaas.git
cd slimfaas/src/SlimFaasPlanetSaver
npm i
npm run dev
```
This will launch a local dev server, letting you see `SlimFaasPlanetSaver` in action.

---

## Configuration Options
When you create a `new SlimFaasPlanetSaver(baseUrl, options)`, you can provide the following optional properties in the `options` object:

| Property                  | Type                                                                 | Default                                                                                   | Description                                                                                                                                                                                                                     |
|---------------------------|----------------------------------------------------------------------|-------------------------------------------------------------------------------------------|---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|
| updateCallback            | `(data: any[]) => void`                                              | `() => {}`                                                                                | Function called after a successful fetch of the functions’ status. The array data includes objects with info about each function, for example: `[{ Name: 'myFunc', NumberReady: 1 }, ...]`.                                     |
| errorCallback             | `(errorMessage: string) => void`                                     | `() => {}`                                                                                | Function called if an error occurs during the status fetch (e.g., network error). Receives an errorMessage string.                                                                                                              |
| interval                  | `number`                                                             | `5000`                                                                                    | How frequently (in ms) the polling should run.                                                                                                                                                                                  |
| overlayStartingMessage    | `string`                                                             | `"🌳 Starting the environment.... 🌳"`                                                    | Main message shown on the overlay when the environment is waking up.                                                                                                                                                            |
| overlayNoActivityMessage  | `string`                                                             | `"Waiting activity to start environment..."`                                              | Message shown if there is no user activity (mouse movement) for too long, but the environment is not ready yet.                                                                                                                 |
| overlayErrorMessage       | `string`                                                             | `"An error occurred while starting the environment."`                                     | Main message shown on the overlay if an error occurs (e.g., network error).                                                                                                                                                     |
| overlaySecondaryMessage   | `string`                                                             | `"Startup should be fast, but if no machines are available it can take several minutes."` | Secondary message shown on the overlay when the environment is waking up.                                                                                                                                                       |
| overlayErrorSecondaryMessage | `string`                                                             | `"If the error persists, please contact an administrator."`                               | Secondary message shown on the overlay when an error occurs.                                                                                                                                                                    |
| overlayLoadingIcon        | `string`                                                             | `"🌍"`                                                                                    | Text or icon shown on the overlay. By default, it is animated to spin.                                                                                                                                                          |
| noActivityTimeout         | `number`                                                             | `60000`                                                                                   | How long (in ms) to wait for mouse movement before concluding there is no activity. If no activity is detected, a different overlay message is displayed.                                                                       |
| wakeUpTimeout             | `number`                                                             | `60000`                                                                                   | If a function was recently “woken up,” we’ll skip re-calling wake-up for that function within this timeout window (in ms).                                                                                                      |
| fetch                     | `typeof fetch`                                                       | Global fetch                                                                              | Custom fetch function if you want to provide your own (e.g., for SSR, or if your environment doesn't have a global fetch).                                                                                                      |
| behavior                  | `{ [functionName: string]: 'WakeUp+BlockUI' \| 'WakeUp' \| 'None' }` | *Not set; defaults each function to "WakeUp+BlockUI" if unspecified*                      | Allows you to override how each function is handled: 1. `"WakeUp+BlockUI"`: wakes the function and blocks the UI with the overlay until it’s ready. 2. `"WakeUp"`: wakes without blocking the UI. 3. `"None"`: no wake-up call. |

### Notes on Behavior
If a function is **not** specified in the behavior map, it defaults to `"WakeUp+BlockUI"`.

- `"WakeUp+BlockUI"` means the overlay will be shown until that function is `NumberReady >= 1`.
- `"WakeUp"` means we attempt to wake up the function, but do not keep the overlay shown specifically for that function.
- `"None"` means the function will neither be woken up nor block the UI.

### Lifecycle

1. **Initialize**
Call `instance.initialize()` to create the overlay elements, inject styles, and bind event listeners (e.g., for mouse movement).

2. **Start Polling**
Call `instance.startPolling()` to begin the periodic checks of the environment. If the environment is not ready, the overlay will appear.

3. **Stop Polling / Cleanup**
When your component unmounts or you no longer need to monitor the environment, call `instance.cleanup()`. This removes the overlay, styles, and any timers or event listeners.

# Agent plugin: NodeAttestor "aws_iid"

*Must be used in conjunction with the [server-side aws_iid plugin](plugin_server_nodeattestor_aws_iid.md)*

The `aws_iid` plugin automatically attests instances using the AWS Instance
Metadata API and the AWS Instance Identity document. It also allows an operator
to use AWS Instance IDs when defining SPIFFE ID attestation policies.

Generally no plugin data is needed in AWS, and this configuration should be used:

```hcl
    NodeAttestor "aws_iid" {
        plugin_data {}
    }
```

| Configuration         | Description                                        |
|-----------------------|----------------------------------------------------|
| ec2_metadata_endpoint | Endpoint for AWS SDK to retrieve instance metadata |

For testing or non-standard AWS environments, you may need to specify the
Metadata endpoint.  For more information, see [the AWS SDK documentation](https://docs.aws.amazon.com/sdk-for-go/api/aws/ec2metadata/)

```hcl
    NodeAttestor "aws_iid" {
        plugin_data {
            ec2_metadata_endpoint = "http://169.254.169.254/latest"
        }
    }
```

# Server plugin: CredentialComposer "uniqueid"

The `uniqueid` plugin adds the `x509UniqueIdentifier` attribute to the X509-SVID subject for workloads. Server and agent X509-SVIDs are not modified.

The x509UniqueIdentifier is formed from a hash of the SPIFFE ID of the workload.

This plugin is intended for backwards compatibility for deployments that have come to rely on this attribute (introduced in SPIRE 1.4.2 and reverted in SPIRE 1.9.0).

This plugin has no configuration. To use the plugin, add it to the plugins section of the SPIRE Server configuration:

```hcl
plugins {
    CredentialComposer "uniqueid" {}

    // ... other plugins ...
}
```

```json
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "Allow full access to the SPIRE Server role",
            "Effect": "Allow",
            "Principal": {
                "AWS": "arn:aws:iam::111122223333:role/example-assumed-role-name"
            },
            "Action": "kms:*",
            "Resource": "*"
        },
        {
             "Sid": "Allow KMS console to display the key and policy",
             "Effect": "Allow",
             "Principal": {
                 "AWS": "arn:aws:iam::111122223333:root"
             },
             "Action": [
                 "kms:Describe*",
                 "kms:List*",
                 "kms:Get*"
             ],
             "Resource": "*"
        }
    ]
}
```

- The first statement of the policy gives the current SPIRE server assumed role full access to the CMK.
- The second statement allows the keys and policy to be displayed in the KMS console.

#### Custom key policy

It is also possible for the user to define a custom key policy. If the configurable `key_policy_file`
is set, the plugin uses the policy defined in the file instead of the default policy.

## Sample Plugin Configuration

### Basic configuration

```hcl
KeyManager "aws_kms" {
    plugin_data {
        region = "us-east-2"
        key_identifier_file = "./key_metadata"
    }
}
```

### Configuration with tag-based key discovery (recommended)

```hcl
KeyManager "aws_kms" {
    plugin_data {
        region = "us-east-2"
        key_identifier_file = "./key_metadata"
        enable_tag_based_key_discovery = true
    }
}
```

### Configuration with tags

```hcl
KeyManager "aws_kms" {
    plugin_data {
        region = "us-east-2"
        key_identifier_file = "./key_metadata"
        enable_tag_based_key_discovery = true
        key_tags = {
            Environment = "production"
            Team        = "security"
            Component   = "spire"
        }
    }
}
```

## Supported Key Types and TTL

The plugin supports all the key types supported by SPIRE: `rsa-2048`, `rsa-4096`, `ec-p256`, and `ec-p384`.

# Server plugin: KeyManager "hashicorp_vault"

The `hashicorp_vault` key manager plugin leverages HashiCorp Vault to create, maintain, and rotate key pairs, signing
SVIDs as needed.

## Configuration

The plugin accepts the following configuration options:

| key                  | type   | required                                    | description                                                                                                                                          | default              |
|:---------------------|:-------|:--------------------------------------------|:-----------------------------------------------------------------------------------------------------------------------------------------------------|:---------------------|
| key_identifier_file  | string | Required if key_identifier_value is not set | A file path location where information about generated keys will be persisted. See "[Management of keys](#management-of-keys)" for more information. | ""                   |
| key_identifier_value | string | Required if key_identifier_file is not set  | A static identifier for the SPIRE server instance (used instead of `key_identifier_file`).                                                           | ""                   |
| vault_addr           | string |                                             | The URL of the Vault server. (e.g., <https://vault.example.com:8443/>)                                                                               | `${VAULT_ADDR}`      |
| namespace            | string |                                             | Name of the Vault namespace. This is only available in the Vault Enterprise.                                                                         | `${VAULT_NAMESPACE}` |
| transit_engine_path  | string |                                             | Path of the transit engine that stores the keys.                                                                                                     | transit              |
| ca_cert_path         | string |                                             | Path to a CA certificate file used to verify the Vault server certificate. Only PEM format is supported.                                             | `${VAULT_CACERT}`    |
| insecure_skip_verify | bool   |                                             | If true, vault client accepts any server certificates. Should only be used for test environments.                                                    | false                |
| cert_auth            | struct |                                             | Configuration for the Client Certificate authentication method                                                                                       |                      |
| token_auth           | struct |                                             | Configuration for the Token authentication method                                                                                                    |                      |
| approle_auth         | struct |                                             | Configuration for the AppRole authentication method                                                                                                  |                      |
| k8s_auth             | struct |                                             | Configuration for the Kubernetes authentication method                                                                                               |                      |

## Environment Variables

The plugin reads the following environment variables. Variables marked as standard are natively recognized by the Vault CLI and client libraries — see the [Vault documentation](https://developer.hashicorp.com/vault/docs/commands#configure-environment-variables) for the full reference.

| Variable                    | Standard | Description                                                   |
|:----------------------------|:---------|:--------------------------------------------------------------|
| `VAULT_ADDR`                | Yes      | Address of the Vault server                                   |
| `VAULT_CACERT`              | Yes      | Path to a CA certificate file                                 |
| `VAULT_CLIENT_CERT`         | Yes      | Path to a client certificate file (cert auth)                 |
| `VAULT_CLIENT_KEY`          | Yes      | Path to a client private key file (cert auth)                 |
| `VAULT_NAMESPACE`           | Yes      | Vault namespace (Enterprise only)                             |
| `VAULT_TOKEN`               | Yes      | Vault token (token auth)                                      |
| `VAULT_APPROLE_ID`          | **No**   | AppRole role ID — SPIRE-specific, not a Vault SDK variable    |
| `VAULT_APPROLE_SECRET_ID`   | **No**   | AppRole secret ID — SPIRE-specific, not a Vault SDK variable  |
| `VAULT_TRANSIT_ENGINE_PATH` | **No**   | Transit engine path — SPIRE-specific, falls back to `transit` |

The plugin supports **Client Certificate**, **Token**, **AppRole** and **Kubernetes** authentication methods.

- **Client Certificate** method authenticates to Vault using a TLS client certificate.
- **Token** method authenticates to Vault using the token in a HTTP Request header.
- **AppRole** method authenticates to Vault using a RoleID and SecretID that are issued from Vault.
- **Kubernetes** method authenticates to Vault using a Kubernetes Service Account Token.

The configured token needs to be attached to a policy that has at least the following capabilities:

```hcl
path "transit/keys/*" {
  capabilities = ["create", "read", "update", "delete", "list"]
}

path "transit/sign/*" {
  capabilities = ["update"]
}
```

## Client Certificate Authentication

| key                   | type   | required | description                                                                                                          | default                |
|:----------------------|:-------|:---------|:---------------------------------------------------------------------------------------------------------------------|:-----------------------|
| cert_auth_mount_point | string |          | Name of the mount point where TLS certificate auth method is mounted                                                 | cert                   |
| cert_auth_role_name   | string |          | Name of the Vault role. If given, the plugin authenticates against only the named role. Default to trying all roles. |                        |
| client_cert_path      | string |          | Path to a client certificate file. Only PEM format is supported.                                                     | `${VAULT_CLIENT_CERT}` |
| client_key_path       | string |          | Path to a client private key file. Only PEM format is supported.                                                     | `${VAULT_CLIENT_KEY}`  |

```hcl
    KeyManager "hashicorp_vault" {
        plugin_data {
            vault_addr = "https://vault.example.org/"
            ca_cert_path = "/path/to/ca-cert.pem"
            cert_auth {
                cert_auth_mount_point = "test-tls-cert-auth"
                client_cert_path = "/path/to/client-cert.pem"
                client_key_path  = "/path/to/client-key.pem"
            }
            // If specify the role to authenticate with
            // cert_auth {
            //     cert_auth_mount_point = "test-tls-cert-auth"
            //     cert_auth_role_name = "test"
            //     client_cert_path = "/path/to/client-cert.pem"
            //     client_key_path  = "/path/to/client-key.pem"
            // }

            // If specify the key-pair as an environment variable and use the modified mount point
            // cert_auth {
            //    cert_auth_mount_point = "test-tls-cert-auth"
            // }

            // If specify the key-pair as an environment variable and use the default mount point, set the empty structure.
            // cert_auth {}
        }
    }
```

