extern "C" void spin_http_handle_http_request(spin_http_request_t *request,
                                              spin_http_response_t *response) {
  spin_http_string_t header_name;
  spin_http_string_dup(&header_name, "foo");

  spin_http_string_t header_value;
  spin_http_string_dup(&header_value, "bar");

  auto header = static_cast<spin_http_tuple2_string_string_t *>(
      malloc(sizeof(spin_http_tuple2_string_string_t)));

  header->f0 = header_name;
  header->f1 = header_value;

  auto body_string = "Hello World!\n";
  auto body_length = strlen(body_string);
  auto body = static_cast<uint8_t *>(malloc(body_length));
  memcpy(body, body_string, body_length);

  response->status = 200;
  response->headers.is_some = true;
  response->headers.val.ptr = header;
  response->headers.val.len = 1;
  response->body.is_some = true;
  response->body.val.ptr = body;
  response->body.val.len = body_length;
}

use spin_sdk::http::body::IncomingBodyExt;
use spin_sdk::http::{HeaderValue, Request, Response};
use spin_sdk::http_service;

#[http_service]
async fn add_animal_fact_header(
    request: Request,
) -> Result<Response, spin_sdk::wasip3::http::types::ErrorCode> {
    // Gather an animal fa-- I MEAN MAKE A REQUEST TO THE AUTHORISATION SERVICE
    let animal_fact_response =
        spin_sdk::http::get("https://random-data-api.fermyon.app/animals/json").await?;
    let animal_fact_json = animal_fact_response.into_body().bytes().await?;
    let animal_fact: AnimalFact = serde_json::from_slice(&animal_fact_json).unwrap();

    // Add a header to the request being passed along the pipeline.
    let (mut parts, body) = request.into_parts();
    parts.headers.append(
        "animal-fact",
        HeaderValue::from_str(&animal_fact.fact).unwrap(),
    );

    // Reconstruct the request, now with the adjusted headers
    let request = Request::from_parts(parts, body);

    // Pass the request on down the middleware pipeline,
    // and return the response unaltered.
    spin_sdk::http::next(request).await
}

